const page = await browser.goto('https://github.com/search?q=OpenClaw&type=repositories');
const text = await browser.js(`
  (() => {
    const items = Array.from(document.querySelectorAll('a[href*="/"]')).filter(a => a.href.match(/github\\.com\\/[^\\/]+\\/[^\\/]+$/));
    const seen = new Set();
    const results = [];
    for (const a of items) {
      if (!seen.has(a.href)) {
        seen.add(a.href);
        results.push({href: a.href, text: a.textContent.trim()});
      }
    }
    return results.slice(0, 30);
  })()
`);
return text;

